def show_initial_cache(self):
        p = self.params()
        if not p:
            return
        payload = load_local_snapshot(p["date"], p["holes"])
        if payload:
            self.context = p
            self.render_snapshot(payload, "Saved on this device")
        self._cache_search_timer.start(100)

